function DiamondSet() {
  return (
    <>
      {DIAMONDS.map((d, i) => (
        <g key={i} className="arcana-logo-d" style={{ ["--d" as string]: DELAY[i] }}>
          <rect
            x={d.x}
            y={d.y}
            width="81.8374"
            height="81.8374"
            rx="9"
            transform={`rotate(45 ${d.x} ${d.y})`}
            fill={d.fill}
          />
        </g>
      ))}
    </>
  );
}

function ArcanaMark({
  className,
  animate = false,
  loop = false,
  hoverAnimate = false,
  lockup = false,
  label = "Arcana",
}: {
  className?: string;
  animate?: boolean;
  loop?: boolean;
  hoverAnimate?: boolean;
  lockup?: boolean;
  label?: string;
}) {
  const motion = loop ? "is-loop" : animate ? "is-in" : "";
  return (
    <svg
      viewBox={lockup ? "0 0 1444 263" : "0 0 412 263"}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={`arcana-logo ${motion} ${hoverAnimate ? "is-hover" : ""} ${className ?? ""}`}
      role="img"
      aria-label={label}
    >
      <DiamondSet />
      {lockup && <path d={WORDMARK} fill="#257DDB" />}
    </svg>
  );
}

export function hideBootSplash() {
  document.getElementById("boot-splash")?.remove();
}

export function BrandMark({
  className = "h-8 w-auto",
  animate = false,
  loop = false,
  hoverAnimate = false,
}: {
  className?: string;
  animate?: boolean;
  loop?: boolean;
  hoverAnimate?: boolean;
}) {
  return <ArcanaMark className={className} animate={animate} loop={loop} hoverAnimate={hoverAnimate} />;
}

export function BrandLockup({
  className = "h-10 w-auto",
  animate = true,
}: {
  className?: string;
  animate?: boolean;
}) {
  return <ArcanaMark className={className} animate={animate} lockup label="Arcana WorkSquare" />;
}

export function Brand({
  compact = false,
  className,
  animate,
}: {
  compact?: boolean;
  className?: string;
  animate?: boolean;
}) {
  return compact ? (
    <BrandMark className={className ?? "h-8 w-auto"} animate={animate} />
  ) : (
    <BrandLockup className={className ?? "h-11 w-auto"} animate={animate ?? true} />
  );
}
